import 'dart:io';

/// Rewrites `test/all_tests_test.dart` so that a bare `flutter test` runs every
/// `lib/**/__tests__/*_test.dart`. The generated file also carries a test
/// that fails when a new `__tests__` file exists but was never registered.
///
///   dart run tool/gen_all_tests.dart
void main() {
  final tests = _discoverTests();
  final target = File('test/all_tests_test.dart')
    ..createSync(recursive: true)
    ..writeAsStringSync(_render(tests));
  Process.runSync(Platform.resolvedExecutable, ['format', target.path]);
  stdout.writeln('Registered ${tests.length} test files in ${target.path}');
}

List<String> _discoverTests() =>
    Directory('lib')
        .listSync(recursive: true)
        .whereType<File>()
        .map((f) => f.path.replaceAll(r'\', '/'))
        .where((p) => p.contains('/__tests__/') && p.endsWith('_test.dart'))
        .toList()
      ..sort();

String _render(List<String> tests) {
  final b = StringBuffer()
    ..writeln(
      '// GENERATED by `dart run tool/gen_all_tests.dart`. Do not edit.',
    )
    ..writeln()
    ..writeln("import 'dart:io';")
    ..writeln()
    ..writeln("import 'package:flutter_test/flutter_test.dart';");
  for (final (i, path) in tests.indexed) {
    final pkgPath = path.replaceFirst('lib/', 'package:selfbox/');
    b.writeln("import '$pkgPath' as t$i;");
  }
  b
    ..writeln()
    ..writeln('const _registered = <String>[');
  for (final path in tests) {
    b.writeln("  '$path',");
  }
  b
    ..writeln('];')
    ..writeln()
    ..writeln('void main() {');
  for (final (i, path) in tests.indexed) {
    b.writeln("  group('$path', t$i.main);");
  }
  b
    ..writeln()
    ..writeln("  test('registers every lib/**/__tests__/*_test.dart', () {")
    ..writeln("    final onDisk = Directory('lib')")
    ..writeln('        .listSync(recursive: true)')
    ..writeln('        .whereType<File>()')
    ..writeln(r"        .map((f) => f.path.replaceAll(r'\', '/'))")
    ..writeln(
      "        .where((p) => p.contains('/__tests__/') && p.endsWith('_test.dart'))",
    )
    ..writeln('        .toList()')
    ..writeln('      ..sort();')
    ..writeln('    expect(')
    ..writeln('      onDisk,')
    ..writeln('      _registered,')
    ..writeln("      reason: 'Run: dart run tool/gen_all_tests.dart',")
    ..writeln('    );')
    ..writeln('  });')
    ..writeln('}');
  return b.toString();
}
